/** Polls until the condition holds or half a second has passed, so a test reads the state it waited for. */
export async function eventually(check: () => boolean): Promise<void> {
  let waited = 0;
  while (!check() && waited < 500) {
    await new Promise(resolve => setTimeout(resolve, 10));
    waited += 10;
  }
}

/** Terminates the clients, lets each server see its sockets close, then stops it, so no close is logged after the logger is restored. */
export async function closeSocketsThenStop(
  openServers: Array<ReturnType<typeof createServer>>,
  openClients: WebSocket[]
): Promise<void> {
  openClients.splice(0).forEach(client => client.terminate());
  for (const hal of openServers.splice(0)) {
    await eventually(() => hal.wss.clients.size === 0);
    await hal.stop();
  }
}

/** A store with only the five required members, so an optional one can be added, replaced or left out per test. */
export function delegatingTo(inner: InMemorySessionStore): SessionStore {
  return {
    create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
    get: sessionId => inner.get(sessionId),
    delete: sessionId => inner.delete(sessionId),
    count: () => inner.count(),
    clear: () => inner.clear(),
  };
}
